  data.items.forEach((row,i)=>{const n=row[side],paths=graphNodeConflictPaths(result,row.id,{includeResolved:true,graphPath:data.graphPath}),enabled=paths.length>0,g=svgNode('g',{'data-node-id':row.id,'data-node-state':n?.state||'missing'}),rect=svgNode('rect',{x:42,y:16+i*68,width:184,height:48,rx:4,fill:!n?'#24292f':n.state==='added'?'#294e40':n.state==='changed'?'#574b2c':'#303b47',stroke:enabled?'#9ebbd8':'#59616a','stroke-dasharray':n?0:4}),text=svgNode('text',{x:50,y:35+i*68,fill:'#ecf0f4','font-size':11}),detail=svgNode('text',{x:50,y:52+i*68,fill:'#b7c3cf','font-size':9}),title=svgNode('title');text.textContent=(n?.label||row.id).slice(0,25);detail.textContent=n?n.key.slice(0,32):'없음';title.textContent=row.id+(n?.changedKeys.length?' · '+n.changedKeys.join(', '):'');g.append(rect,text,detail,title);if(enabled){g.setAttribute('role','button');g.setAttribute('aria-pressed',String(paths.every(id=>result.resolved.some(r=>r.id===id&&r.choice===side))));g.setAttribute('tabindex','0');g.setAttribute('aria-label',row.id+' '+label+' 충돌 선택');g.onclick=()=>panel.chooseNode(row.id,side);g.onkeydown=e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();panel.chooseNode(row.id,side);}};}svg.append(g);});scroll.append(svg);columns.append(column);
